('7d036969-831d-4dd8-a219-1c493d7aacb4','Willow & Rye Barn','demo-willow-rye-barn','Venue','Charlottesville','VA','US','A restored 1890s timber barn on forty acres, seating up to 240 under string lights. Long-table dinners, a covered ceremony lawn, parking for 90 cars, and a cottage that sleeps six. A rain plan is included with every booking.','https://example.com/willow-rye','/__l5e/assets-v1/02f7e21d-1bbc-4f1c-b821-476de6e4d259/vendor-venue.jpg','["/__l5e/assets-v1/02f7e21d-1bbc-4f1c-b821-476de6e4d259/vendor-venue.jpg"]','$6,000 - $12,000','verified', now(), true),
('7d036969-831d-4dd8-a219-1c493d7aacb4','Marrow & Mint Catering','demo-marrow-mint','Catering','Richmond','VA','US','Seasonal Southern menus built around what is good that week. Family-style platters, stations, or plated service for 20 to 400 guests. Full allergen handling, including halal and gluten-free lines cooked separately.','https://example.com/marrow-mint','/__l5e/assets-v1/93f6bd20-c548-42fb-b860-cf289060d866/vendor-catering.jpg','["/__l5e/assets-v1/93f6bd20-c548-42fb-b860-cf289060d866/vendor-catering.jpg"]','$48 - $95 per guest','verified', now(), true),
('7d036969-831d-4dd8-a219-1c493d7aacb4','Alder Lane Photography','demo-alder-lane','Photography','Washington','DC','US','Documentary coverage of family gatherings, reunions and weddings. Two photographers, no posed lineups unless you want them, and a private gallery delivered within ten days. Reunion packages cover multi-day events.','https://example.com/alder-lane','/__l5e/assets-v1/7915defe-f239-4b3f-8fe3-a5cd9ce963f2/vendor-photo.jpg','["/__l5e/assets-v1/7915defe-f239-4b3f-8fe3-a5cd9ce963f2/vendor-photo.jpg"]','$2,200 - $5,400','verified', now(), true),
('7d036969-831d-4dd8-a219-1c493d7aacb4','Fern & Fold Florals','demo-fern-fold','Florist','Alexandria','VA','US','Garden-style arrangements grown or sourced within 200 miles. Arches, tablescapes, and hand-tied bouquets, plus a rental library of vessels and stands so nothing is bought twice.','https://example.com/fern-fold','/__l5e/assets-v1/d7eecf69-d4ea-46ac-93d0-2055d4ed6e91/vendor-florist.jpg','["/__l5e/assets-v1/d7eecf69-d4ea-46ac-93d0-2055d4ed6e91/vendor-florist.jpg"]','$900 - $4,000','verified', now(), true),
('7d036969-831d-4dd8-a219-1c493d7aacb4','The Brass Union','demo-brass-union','Band','Baltimore','MD','US','Seven-piece soul and Motown band with a two-piece horn section. Ceremony trio, cocktail set, and three dance sets under one fee. PA and lighting supplied, with a DJ set between bands so the floor never empties.','https://example.com/brass-union','/__l5e/assets-v1/01e53351-aab3-4517-aab6-39f089c6b27c/vendor-band.jpg','["/__l5e/assets-v1/01e53351-aab3-4517-aab6-39f089c6b27c/vendor-band.jpg"]','$3,800 - $7,500','verified', now(), true),
('7d036969-831d-4dd8-a219-1c493d7aacb4','Sugar House Bakeshop','demo-sugar-house','Cake & Dessert','Bethesda','MD','US','Celebration cakes, dessert tables, and travel-safe boxed sweets for out-of-town guests. Tasting boxes ship before you commit, and every recipe is available nut-free on request.','https://example.com/sugar-house','/__l5e/assets-v1/4e5c8a96-67c9-4aa0-8235-bcd623037b43/vendor-cake.jpg','["/__l5e/assets-v1/4e5c8a96-67c9-4aa0-8235-bcd623037b43/vendor-cake.jpg"]','$350 - $1,400','verified', now(), true)
